from pathlib import Path
R=Path(__file__).resolve().parents[1]
payload=(R/'tmp/pdfs/doc02/reader_payload.json').read_text()
page='''<!doctype html><html lang="hu"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IndaPlay audit · Olvasó</title>
<style>
:root{--ink:#203746;--muted:#617785;--teal:#155d66;--line:#d8e3e6;--paper:#fff;--bg:#eef3f3}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.65 system-ui,sans-serif}button,input{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer;background:white;color:var(--teal);border:1px solid var(--line);border-radius:8px;padding:7px 12px}button:hover{background:#e5f2f1}button:disabled{opacity:.4;cursor:default}button.active{background:var(--teal);color:white}header{position:sticky;top:0;z-index:5;padding:12px 24px;background:#123b46;color:white;display:flex;gap:16px;align-items:center;justify-content:space-between}header strong{display:block;font-size:18px}header small{color:#b8d6dc;font-size:12px}header nav{display:flex;gap:8px;flex-wrap:wrap}header button{font-size:14px}aside{width:300px;position:fixed;top:88px;bottom:0;overflow:auto;padding:20px;border-right:1px solid var(--line);font-size:13px}aside label{font-weight:650;display:block}#query{width:100%;padding:9px;border:1px solid #aac1c7;border-radius:7px;background:white;font-size:14px}#results{margin:15px 0}#results button,#toc button{display:block;text-align:left;width:100%;background:transparent;border:0;border-bottom:1px solid var(--line);border-radius:0;font-size:13px;padding:10px 4px;line-height:1.5}#results small{display:block;color:var(--muted)}#results button:hover,#toc button:hover{background:#dce9e9}#toc summary{font-weight:650;cursor:pointer;padding:8px 0}main{margin-left:300px;padding:28px 36px 80px;max-width:1370px}#toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:0 0 18px;font-size:14px}#pageInput{width:66px;padding:5px;border:1px solid var(--line);border-radius:5px}article{background:var(--paper);padding:42px 48px;border:1px solid var(--line);border-radius:12px;box-shadow:0 7px 26px #173d4710;overflow-wrap:anywhere}article>p{max-width:82ch}h1,h2,h3,h4{line-height:1.3;color:var(--teal);scroll-margin-top:100px}h1{font-size:34px}h2{font-size:27px;margin-top:1.9em}h3{font-size:21px;margin-top:1.5em}h4{font-size:18px}.subtitle{font-size:25px;font-weight:650;color:var(--teal)}.note{background:#eaf4f3;border-left:4px solid #47888b;padding:16px 20px;font-size:15px}.ref{font-size:12px;color:var(--muted);letter-spacing:.04em;margin-bottom:24px}.tablewrap{overflow-x:auto;margin:22px 0}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.5}td,th{padding:12px 14px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left;min-width:90px}th{background:var(--teal);color:white}tr:nth-child(even){background:#f0f5f6}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f0f4f6;padding:18px;border-radius:6px;font:13px/1.6 ui-monospace,monospace}.bullet{padding-left:18px;border-left:2px solid var(--line)}figure{margin:28px 0}figure img{display:block;max-width:100%;height:auto;margin:auto}figcaption{font-size:12px;color:var(--muted);margin:10px 0}article .tocline{font-size:13px;line-height:1.5}footer{font-size:12px;color:var(--muted);padding-top:20px}mark{background:#fff0a6;color:inherit}#status{font-size:12px;color:var(--muted)}.break{border:0;border-top:1px solid var(--line);margin:44px 0}button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #e6ac32;outline-offset:2px}
@media(max-width:850px){header{position:relative;padding:14px;align-items:flex-start;flex-direction:column;gap:10px}aside{position:relative;top:auto;bottom:auto;width:100%;max-height:340px;border-bottom:1px solid var(--line);padding:16px}main{margin:0;padding:18px 12px 50px}article{padding:24px 20px}h1{font-size:29px}h2{font-size:24px}td,th{padding:9px}#toc{margin-top:10px}}@media print{header,aside,#toolbar,footer{display:none}main{margin:0;padding:0}article{border:0;box-shadow:none;padding:0}table{font-size:10px}}
</style>
<header><div><strong>IndaPlay · Audit olvasó</strong><small>DOC02 · 2026. május 6. · Bizalmas</small></div><nav aria-label="Nézet"><button id="guideBtn">Eligazító</button><button id="fullBtn">Teljes dokumentum</button><button id="originalBtn">Eredeti PDF ↗</button></nav></header>
<aside><label for="query">Keresés mind a 311 forrásoldalon</label><input id="query" type="search" placeholder="Pl. voucher, Redis, mentés…" autocomplete="off"><div id="results" aria-live="polite"></div><details id="toc" open><summary>Fejezetek · eredeti oldalszám</summary><div id="tocItems"></div></details><p id="status">Helyben működik, internetkapcsolat nélkül.</p></aside>
<main><div id="toolbar" hidden><button id="prev" aria-label="Előző forrásoldal">← Előző</button><label for="pageInput">Eredeti oldal</label><input type="number" min="1" max="311" id="pageInput" value="1"><span>/ 311</span><button id="goto">Ugrás</button><button id="next" aria-label="Következő forrásoldal">Következő →</button></div><article id="content"></article><footer>A magyarázat külön szerkesztői réteg. A forrásszöveg állításai és utasításai a dokumentum tartalmához tartoznak. Feldolgozás: 2026. szeptember 14.</footer></main>
<script type="application/json" id="data">__PAYLOAD__</script>
<script>
'use strict';const data=JSON.parse(document.getElementById('data').textContent);const el=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const norm=s=>s.toLocaleLowerCase('hu').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'');let current=1,mode='guide',pdfURL=null;
function block(b){let t=esc(b.text||'');if(b.kind==='table'){let rows=b.inherited_header?[b.inherited_header,...b.rows]:b.rows;let header=b.inherited_header||b.header!==false;return '<div class="tablewrap"><table>'+rows.map((row,i)=>'<tr>'+row.map(c=>{let tag=header&&i===0?'th':'td';return '<'+tag+'>'+esc(c).replace(/\\n/g,'<br>')+'</'+tag+'>'}).join('')+'</tr>').join('')+'</table></div>'}if(b.kind==='image')return '<figure><img loading="lazy" src="'+esc(b.image_url)+'" alt="Az eredeti PDF teljes beágyazott ábrája"><figcaption>Eredeti ábra, teljes méretben megőrizve. Nagyításhoz használd a böngésző nagyítását.</figcaption></figure>';if(b.kind==='pagebreak'||b.kind==='rule')return '<hr class="break">';if(b.kind==='code')return '<pre>'+t+'</pre>';let tag={title:'h1',h1:'h2',h2:'h3',h3:'h4',h4:'h4'}[b.kind]||'p';return '<'+tag+' class="'+({note:'note',subtitle:'subtitle',toc:'tocline',bullet:'bullet'}[b.kind]||'')+'">'+t+'</'+tag+'>'}
function render(scroll=true){let guide=mode==='guide';el('toolbar').style.display=guide?'none':'flex';el('guideBtn').classList.toggle('active',guide);el('fullBtn').classList.toggle('active',!guide);el('pageInput').value=current;el('prev').disabled=current===1;el('next').disabled=current===311;el('content').innerHTML=guide?data.guide.map(block).join(''):'<div class="ref">FORRÁSSZÖVEG · DOC02-P'+String(current).padStart(3,'0')+' · EREDETI PDF '+current+'. OLDAL</div>'+data.pages[current-1].blocks.map(block).join('');if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function page(n){current=Math.max(1,Math.min(311,Math.round(Number(n)||1)));mode='full';location.hash='page='+current;render()}
el('guideBtn').onclick=()=>{mode='guide';location.hash='guide';render()};el('fullBtn').onclick=()=>page(current);el('prev').onclick=()=>page(current-1);el('next').onclick=()=>page(current+1);el('goto').onclick=()=>page(el('pageInput').value);el('pageInput').onkeydown=e=>{if(e.key==='Enter')page(e.target.value)};el('originalBtn').onclick=()=>{if(!pdfURL){const raw=atob(data.pdf),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);pdfURL=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}))}window.open(pdfURL+'#page='+(mode==='guide'?1:current),'_blank','noopener')};
el('tocItems').innerHTML=data.toc.map(t=>'<button data-page="'+t.page+'">'+esc(t.title)+' <strong>· '+t.page+'.</strong></button>').join('');el('tocItems').onclick=e=>{let b=e.target.closest('button');if(b)page(b.dataset.page)};
const index=data.pages.map(p=>({page:p.page,text:p.blocks.map(b=>b.text||(b.rows?b.rows.map(r=>r.join(' ')).join(' '):'')).join(' ')})).map(p=>({...p,normalized:norm(p.text)}));let debounce;el('query').oninput=()=>{clearTimeout(debounce);debounce=setTimeout(search,160)};
function search(){const q=norm(el('query').value.trim());if(!q){el('results').innerHTML='';return}const hits=index.filter(p=>p.normalized.includes(q));el('results').innerHTML='<p><strong>'+hits.length+' találati oldal</strong></p>'+hits.map(p=>{let i=p.normalized.indexOf(q),start=Math.max(0,i-60),excerpt=p.text.slice(start,i+q.length+120);return '<button data-page="'+p.page+'"><strong>'+p.page+'. oldal</strong><small>'+esc((start?'…':'')+excerpt+'…')+'</small></button>'}).join('')}
el('results').onclick=e=>{let b=e.target.closest('button');if(b)page(b.dataset.page)};window.onhashchange=()=>{let m=location.hash.match(/^#page=(\\d+)$/);if(m){current=Math.max(1,Math.min(311,Number(m[1])));mode='full'}else mode='guide';render(false)};if(location.hash.startsWith('#page=')){current=Math.max(1,Math.min(311,Number(location.hash.slice(6))||1)));mode='full'}render(false);
</script></html>'''
# Correct balance in the initial hash parser.
page=page.replace("Number(location.hash.slice(6))||1)))","Number(location.hash.slice(6))||1))")
out=R/'output/notes/doc02/indaplay_audit_olvaso.hu.html'
out.write_text(page.replace('__PAYLOAD__',payload));print(out, out.stat().st_size)
